import { DatabaseSync } from 'node:sqlite';
import { likeMatch } from '../src/index';

/**
 * Empirical parity proof for `likeMatch` (`SPEC-service-kernel` "Shared
 * primitives"; ported from `apps/note-service/test/content-match.test.ts`).
 *
 * Expected `LIKE` results are generated by a real SQLite query — never
 * hand-coded — so the comparator is pinned to the engine's actual semantics. The
 * database is an in-memory `node:sqlite` instance (zero third-party runtime
 * deps); no fixture file is ever opened.
 */

/** Expected result straight from SQLite: `text LIKE pattern` (1/0 → boolean). */
function sqliteLike(text: string, pattern: string): boolean {
  const db = new DatabaseSync(':memory:');
  try {
    const row = db.prepare('SELECT (? LIKE ?) AS m').get(text, pattern);
    return Number(row?.m) === 1;
  } finally {
    db.close();
  }
}

describe('likeMatch: SQLite LIKE parity (empirically generated expectations)', () => {
  it('equals SQLite LIKE over an ASCII corpus', () => {
    // `q` is wrapped exactly as the service binds it today: `%${q}%`. The corpus
    // covers case variants, `%`/`_` wildcards typed by the user, empty patterns,
    // and leading/trailing characters. ASCII only — the Unicode fold is the
    // documented deviation and is asserted separately.
    const texts = [
      'Hello World',
      'hello world',
      'HELLO',
      'abc_def_ghi',
      '100% pure',
      'under_score',
      'MiXeD CaSe',
      'trailing ',
      ' leading',
      'a',
      '_',
      '%',
      '',
    ];
    const queries = [
      'hello',
      'HELLO',
      'World',
      'o w',
      'abc',
      '_def',
      '100%',
      '%',
      '_',
      'def_ghi',
      'zzz',
      '',
      'A',
      'a',
      'trailing',
      'leading',
      '% p',
    ];

    const mismatches: Array<Record<string, unknown>> = [];
    for (const text of texts) {
      for (const q of queries) {
        const pattern = `%${q}%`;
        const expected = sqliteLike(text, pattern);
        const actual = likeMatch(text, pattern);
        if (actual !== expected) mismatches.push({ text, q, pattern, expected, actual });
      }
    }

    expect(mismatches).toEqual([]);
  });

  it('documents the Unicode-folding deviation (broader fold than SQLite LIKE)', () => {
    // SQLite `LIKE` folds ASCII A–Z only, so a non-ASCII case pair does not match.
    expect(sqliteLike('CAFÉ', '%café%')).toBe(false);
    // `toLowerCase()` folds Unicode too, so the comparator matches. This is the
    // accepted, documented deviation (SPEC-service-kernel parity contract).
    expect(likeMatch('CAFÉ', '%café%')).toBe(true);

    // `İ` (U+0130) lowercases to `i` + a combining dot, so `%i%` matches in JS.
    expect(likeMatch('İstanbul', '%i%')).toBe(true);
    // SQLite's ASCII-only fold does not see an `i` there.
    expect(sqliteLike('İstanbul', '%i%')).toBe(false);
  });

  it('treats % and _ as the engine does: active wildcards, not literals', () => {
    expect(likeMatch('abc_def', '%abc_def%')).toBe(true);
    expect(likeMatch('abcXdef', '%abc_def%')).toBe(true); // `_` = one char
    expect(likeMatch('abc', 'abc%')).toBe(true); // trailing `%` matches empty
    expect(likeMatch('anything', '%')).toBe(true);
    expect(likeMatch('', '')).toBe(true);
    expect(likeMatch('x', '')).toBe(false);
  });
});
